#!/usr/bin/env python3
"""Cursor `afterFileEdit` hook — best-effort claim-lease warning.

`afterFileEdit` fires AFTER the edit and cannot block (Cursor exposes no
`beforeFileEdit`), so this WARNS rather than prevents: if an edited file falls outside
the claimed item's touchpoints, it surfaces a message so the agent double-checks it
isn't colliding with another worker. Silent (fail-open) when nothing is claimed.

The claim manifest is read from GRAPHBAN_CLAIM_FILE (or the older AGENTLEDGER_CLAIM_FILE)
(default `.cursor/graphban-claim.json`, falling back to the older
`.cursor/agentledger-claim.json`) — see `.cursor/graphban-claim.example.json`.
A fuller version would query the live claim over MCP and block pre-edit once Cursor
exposes a blocking file hook; that's a follow-up.

I/O: reads `{file_path, workspace_roots, ...}` on stdin; writes `{}` (silent) or
`{"user_message": "..."}` on stdout.
"""
import fnmatch
import json
import os
import sys
from pathlib import Path


def rel_to_workspace(file_path, roots):
    p = Path(file_path)
    for root in roots or []:
        try:
            return p.resolve().relative_to(Path(root).resolve()).as_posix()
        except Exception:
            continue
    return p.name


def matches(rel, touchpoint):
    """Match Graphban-style: exact, glob, or directory prefix."""
    tp = (touchpoint or "").strip()
    if not tp:
        return False
    if fnmatch.fnmatch(rel, tp):
        return True
    base = tp.rstrip("/")
    if rel == base or rel.startswith(base + "/"):
        return True
    return fnmatch.fnmatch(rel, base + "/*")


def load_manifest():
    # Same dual-accept as the CLI config (AL-262): prefer the new name and path, fall
    # back to the old ones, and never move or delete a file the operator already has.
    path = os.environ.get("GRAPHBAN_CLAIM_FILE") or os.environ.get("AGENTLEDGER_CLAIM_FILE")
    if not path:
        candidates = (".cursor/graphban-claim.json", ".cursor/agentledger-claim.json")
        path = next((c for c in candidates if Path(c).exists()), candidates[0])
    try:
        return json.loads(Path(path).read_text())
    except Exception:
        return None


def main():
    try:
        data = json.loads(sys.stdin.read() or "{}")
    except Exception:
        print("{}")
        return
    manifest = load_manifest()
    touchpoints = (manifest or {}).get("touchpoints") or []
    if not manifest or not touchpoints:
        print("{}")  # nothing claimed / no touchpoints declared — fail open
        return
    rel = rel_to_workspace(data.get("file_path", ""), data.get("workspace_roots"))
    if any(matches(rel, tp) for tp in touchpoints):
        print("{}")
        return
    item = manifest.get("item_id", "the claimed item")
    print(json.dumps({
        "user_message": (
            f"Graphban: edited {rel}, which is outside {item}'s touchpoints "
            f"({', '.join(touchpoints)}). Confirm you're not colliding with another "
            f"agent's work — or update the item's touchpoints if this is intended."
        )
    }))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Claim-manifest writer — keeps `.cursor/graphban-claim.json` in step with the claim.

`gb_after_file_edit.py` warns when an edit is outside the touchpoints in that file, but the
server cannot write the checkout, so this local script does. It is the one writer; every
call site runs it:

* Cursor: `afterMCPExecution` in `.cursor/hooks.json` (event JSON on stdin).
* Grok: a `PostToolUse` matcher group in `.grok/hooks/` (same script; Grok maps
  `afterMCPExecution` to `PostToolUse`).
* gbagent: `Graphban.execute` calls `apply_tool_result` directly.

Rules: a `claim_next`/`claim_cluster` result with `claimed: true` replaces the file
(`item_id` = the seed, `touchpoints` = union over the result's items, `agent_id` =
`claimed_by` when present). `claimed: false` or an empty queue leaves the file alone. A
successful `release_item` removes it. Every other tool is ignored. Fail-open: never raises.
"""
import json
import os
import sys
from pathlib import Path

CLAIM_TOOLS = ("claim_next", "claim_cluster")
RELEASE_TOOL = "release_item"
DEFAULT_PATH = ".cursor/graphban-claim.json"


def manifest_path(root=None):
    env = os.environ.get("GRAPHBAN_CLAIM_FILE") or os.environ.get("AGENTLEDGER_CLAIM_FILE")
    if env:
        return Path(env)
    return Path(root or ".") / DEFAULT_PATH


def short_tool(name):
    """`mcp__graphban__claim_next` / `graphban:claim_next` / `claim_next` -> `claim_next`."""
    name = str(name or "")
    for sep in ("__", ":", "."):
        name = name.rsplit(sep, 1)[-1]
    return name


def _items(result):
    if isinstance(result.get("items"), list):
        return [i for i in result["items"] if isinstance(i, dict)]
    if isinstance(result.get("item"), dict):
        return [result["item"]]
    return []


def build_manifest(result):
    """The manifest for a claim result, or None when nothing was claimed."""
    if not isinstance(result, dict) or result.get("claimed") is not True:
        return None
    items = _items(result)
    if not items:
        return None
    touchpoints = []
    for item in items:
        for tp in item.get("touchpoints") or []:
            if tp not in touchpoints:
                touchpoints.append(tp)
    manifest = {"item_id": items[0].get("id"), "touchpoints": touchpoints}
    agent = items[0].get("claimed_by") or result.get("claimed_by")
    if agent:
        manifest["agent_id"] = agent
    return manifest


def _parse(value):
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except Exception:
            return None
    if isinstance(value, dict):
        # MCP envelope: {"structuredContent": {...}} or {"content": [{"text": "{...}"}]}
        if isinstance(value.get("structuredContent"), dict):
            return value["structuredContent"]
        content = value.get("content")
        if isinstance(content, list) and content and isinstance(content[0], dict) \
                and "claimed" not in value and "released" not in value:
            return _parse(content[0].get("text"))
        return value
    return None


def apply_tool_result(tool_name, result, root=None):
    """Write or clear the manifest for one finished tool call. Returns what happened."""
    try:
        tool = short_tool(tool_name)
        result = _parse(result)
        path = manifest_path(root)
        if tool in CLAIM_TOOLS:
            manifest = build_manifest(result)
            if manifest is None:
                return "unchanged"
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(json.dumps(manifest, indent=2) + "\n")
            return "written"
        if tool == RELEASE_TOOL:
            if not isinstance(result, dict) or result.get("error") or result.get("ok") is False \
                    or result.get("released") is False:
                return "unchanged"
            if path.exists():
                path.unlink()
                return "removed"
        return "unchanged"
    except Exception:
        return "unchanged"


def main():
    try:
        event = json.loads(sys.stdin.read() or "{}")
    except Exception:
        print("{}")
        return
    roots = event.get("workspace_roots") or []
    root = roots[0] if roots else event.get("cwd")
    result = event.get("result_json")
    if result is None:
        result = event.get("tool_response", event.get("tool_output"))
    apply_tool_result(event.get("tool_name"), result, root)
    print("{}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Cursor `stop` hook — nudge the agent to close the Graphban loop.

When the agent loop finishes successfully, remind it to move its claimed item to
review and capture lessons. `loop_limit` in hooks.json stops this from re-firing.

CAVEAT: `stop` / `afterAgentResponse` may not fire reliably in Cursor CLOUD agents as
of v3.11 — treat this as a best-effort nudge, not a guarantee. The durable driver of
the loop is the `sessionStart` primer + the sub-agent prompts, not this hook.

I/O: reads `{status, loop_count}` on stdin; writes `{}` or `{"followup_message": "..."}`.
"""
import json
import sys


def main():
    try:
        data = json.loads(sys.stdin.read() or "{}")
    except Exception:
        print("{}")
        return
    if data.get("status") == "completed":
        print(json.dumps({
            "followup_message": (
                "If you completed a claimed item: update_item(status=\"review\") and run "
                "extract_lessons, then get_backlog for the next ready item."
            )
        }))
    else:
        print("{}")


if __name__ == "__main__":
    main()

{
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "claim_next|claim_cluster|release_item",
        "hooks": [
          { "type": "command", "command": "python3 .cursor/hooks/gb_claim_manifest.py" }
        ]
      }
    ]
  }
}
